function HeroSection({ heroImageUrl }) {
  return (
    <section className="hero">
      <img src={heroImageUrl} loading="lazy" alt="Product hero" width="200" height="400"  />
      <h1>Welcome to Acme</h1>
    </section>
  );
}
function App() {
  const [heroImageUrl, setHeroImageUrl] = useState(null);

  useEffect(() => {
    fetch('/api/hero-config')
      .then(res => res.json())
      .then(data => setHeroImageUrl(data.imageUrl));
  }, []);

  if (!heroImageUrl) return <div className="hero-placeholder"  width="200" height="400"> Skeletal loader </div>;

  return <HeroSection heroImageUrl={heroImageUrl} />;
}

